/** 自动生成的 line 图标，来源与许可见 icons.json。 */
import { IconBase, type IconProps } from '../../IconBase.js';

export function LineIcon(props: IconProps) {
  return (
    <IconBase viewBox="0 0 128 128" {...props}>
      <image href="data:image/png;base64," width="128" height="128" />
    </IconBase>
  );
}
